function o(t){if(t==null||t==="")return null;if(t instanceof Date)return Number.isNaN(t.getTime())?null:t;if(typeof t=="number")return!Number.isFinite(t)||t<=0?null:new Date(t<1e12?t*1e3:t);const e=String(t).trim();if(/^\d+$/.test(e)){const i=Number(e);return new Date(i<1e12?i*1e3:i)}const n=new Date(e);return Number.isNaN(n.getTime())?null:n}function f(t){const e=o(t);return e?e.toLocaleString("zh-CN",{hour12:!1}):"—"}function s(t){const e=o(t);return e?e.toLocaleTimeString("zh-CN",{hour12:!1}):"—"}function c(t){const e=o(t);return e?`${e.getFullYear()}-${r(e.getMonth()+1)}-${r(e.getDate())}`:"—"}function g(t){return t==null||Number.isNaN(t)?"—":t.toLocaleString("zh-CN",{maximumFractionDigits:2})}function m(t){return t==null||Number.isNaN(t)?"—":t<1e3?`${Math.round(t)} ms`:`${(t/1e3).toFixed(2)} s`}function r(t){return t<10?`0${t}`:String(t)}function u(t){return`${t.getFullYear()}-${r(t.getMonth()+1)}-${r(t.getDate())}`}function N(t){const e=new Date(t.getFullYear(),t.getMonth(),1),n=new Date(t.getFullYear(),t.getMonth()+1,0);return{from:u(e),to:u(n),days:n.getDate()}}function d(t){return`${t.getFullYear()} 年 ${t.getMonth()+1} 月`}const a=["日","一","二","三","四","五","六"];function l(t,e){const n=new Date(t.getFullYear(),t.getMonth(),e);return a[n.getDay()]}function D(t,e){return!t||!e||e<=0?0:Math.max(0,Math.min(100,Math.round(t/e*100)))}export{f as a,s as b,g as c,c as d,r as e,m as f,N as g,u as h,d as m,D as p,o as t,l as w};
